/// G93: Persian and Hebrew mirror the UI while their strings fall back to
/// English, so each English string comes in a left-to-right isolate
/// (`IsolatedFallbackLocalizations`, generated by `tools/l10n`). Without it,
/// an English string in a right-to-left paragraph reorders: "1 of 2" shows
/// as "of 2 1", "Open file…" as "…Open file".
library;

import 'dart:convert';
import 'dart:io';
import 'dart:math' as math;

import 'package:ferman/design/components/components.dart';
import 'package:ferman/features/settings/settings_screen.dart';
import 'package:ferman/l10n/app_language.dart';
import 'package:ferman/l10n/gen/app_localizations.dart';
import 'package:ferman/l10n/gen/app_localizations_en.dart';
import 'package:ferman/l10n/isolated_fallback.g.dart';
import 'package:flutter/foundation.dart';
import 'package:flutter/rendering.dart';
import 'package:flutter/widgets.dart' hide Icon;
import 'package:flutter_test/flutter_test.dart';

import '../features/onboarding/ferman_app_harness.dart';
import '../helpers/m1_screens.dart';

const String _lri = '\u2066';
const String _pdi = '\u2069';

/// The app languages whose strings are isolated: right to left, without a
/// translation.
const List<String> _isolated = ['fa', 'he'];

/// The app languages whose strings are not: the translated ones, and German
/// as an untranslated left-to-right language.
const List<String> _plain = ['en', 'tr', 'ar', 'de'];

/// Opens [screen] in the app language [code]; returns its strings.
Future<AppLocalizations> _pump(
  WidgetTester tester,
  M1Screen screen,
  String code,
) async {
  await pumpFermanApp(tester, settings: screen.settings(languageCode: code));
  await screen.open(tester);
  return AppLocalizations.of(tester.element(find.byType(screen.widgetType)));
}

/// The paragraph of the one onstage text [text].
RenderParagraph _paragraph(WidgetTester tester, String text) =>
    tester.renderObject<RenderParagraph>(
      find.descendant(of: find.text(text), matching: find.byType(RichText)),
    );

/// The left edge of the glyph at code-unit [offset] in [paragraph].
double _left(RenderParagraph paragraph, int offset) => paragraph
    .getBoxesForSelection(
      TextSelection(baseOffset: offset, extentOffset: offset + 1),
    )
    .first
    .left;

/// Whether [parts] of [text], each found after the previous one, sit from
/// left to right in [paragraph]: the order in which English reads.
bool _readsInOrder(RenderParagraph paragraph, String text, List<String> parts) {
  var from = 0;
  final lefts = <double>[];
  for (final part in parts) {
    final offset = text.indexOf(part, from);
    expect(offset, isNot(-1), reason: '"$part" in "$text"');
    lefts.add(_left(paragraph, offset));
    from = offset + part.length;
  }
  for (var i = 1; i < lefts.length; i++) {
    if (lefts[i] <= lefts[i - 1]) return false;
  }
  return true;
}

/// The right edge of the paragraph's rightmost glyph.
double _rightmostGlyph(RenderParagraph paragraph) => paragraph
    .getBoxesForSelection(
      TextSelection(
        baseOffset: 0,
        extentOffset: paragraph.text.toPlainText().length,
      ),
    )
    .map((box) => box.right)
    .reduce(math.max);

/// The plain text of every onstage text.
List<String> _texts(WidgetTester tester) => [
  for (final element in find.byType(RichText).evaluate())
    (element.renderObject! as RenderParagraph).text.toPlainText(
      includeSemanticsLabels: false,
    ),
];

/// [text] without the fallback isolates.
String _withoutIsolates(String text) =>
    text.replaceAll(_lri, '').replaceAll(_pdi, '');

/// The messages of the abstract gen-l10n class, as `get name` or
/// `name(parameters)` with whitespace collapsed, in source order. A reading
/// of the source independent of `tools/l10n`'s parser.
List<String> _abstractMessages() {
  final source = File('lib/l10n/gen/app_localizations.dart')
      .readAsStringSync()
      .replaceAll(RegExp(r'^\s*///.*$', multiLine: true), '');
  final start = source.indexOf('abstract class AppLocalizations');
  final body = source.substring(start, source.indexOf('\n}\n', start));
  return [
    for (final match in RegExp(
      r'^  String (?:get (\w+)|(\w+)\(([^)]*)\));$',
      multiLine: true,
    ).allMatches(body))
      if (match.group(1) != null)
        'get ${match.group(1)}'
      else
        '${match.group(2)}(${_collapse(match.group(3)!)})',
  ];
}

/// The overrides of `IsolatedFallbackLocalizations`, in the same form,
/// each checked to return `isolate(super.name)` or `isolate(super.name(a,
/// b))`: the same member, with every parameter passed on in order.
List<String> _generatedOverrides() {
  final source = File('lib/l10n/isolated_fallback.g.dart').readAsStringSync();
  final start = source.indexOf('final class IsolatedFallbackLocalizations ');
  final body = source.substring(start, source.indexOf('\n}\n', start));
  final overrides = <String>[];
  for (final match in RegExp(
    r'@override\s+String (?:get (\w+) =>\s*isolate\(super\.(\w+)\);'
    // A long call is formatted over lines, with a trailing comma.
    r'|(\w+)\(([^)]*)\) =>\s*isolate\(\s*super\.(\w+)\(([^)]*)\),?\s*\);)',
  ).allMatches(body)) {
    if (match.group(1) case final name?) {
      expect(match.group(2), name, reason: 'get $name wraps super.$name');
      overrides.add('get $name');
      continue;
    }
    final name = match.group(3)!;
    final parameters = _collapse(match.group(4)!);
    expect(match.group(5), name, reason: '$name wraps super.$name');
    final names = [
      for (final parameter in parameters.split(', '))
        if (parameter.isNotEmpty) parameter.split(' ').last,
    ];
    expect(
      _collapse(match.group(6)!),
      names.join(', '),
      reason: '$name passes every parameter on',
    );
    overrides.add('$name($parameters)');
  }
  expect(
    '@override'.allMatches(body).length,
    overrides.length,
    reason: 'every override of the class is a wrapped message',
  );
  return overrides;
}

String _collapse(String text) =>
    text.replaceAll(RegExp(r'\s+'), ' ').trim().replaceAll(RegExp(r',$'), '');

void main() {
  group('IsolatedFallbackLocalizations (G93)', () {
    test('overrides every message of AppLocalizations, in order', () {
      final messages = _abstractMessages();
      expect(messages, hasLength(greaterThan(250)));
      expect(
        _generatedOverrides(),
        messages,
        reason:
            'lib/l10n/isolated_fallback.g.dart is stale; run '
            '(cd tools/l10n && dart run l10n)',
      );
    });

    test('has one override per message of app_en.arb', () {
      final arb = json.decode(
        File('lib/l10n/app_en.arb').readAsStringSync(),
      ) as Map<String, Object?>;
      final keys = [
        for (final key in arb.keys)
          if (!key.startsWith('@')) key,
      ];
      expect(
        _generatedOverrides().map(
          (override) => override.replaceFirst('get ', '').split('(').first,
        ),
        unorderedEquals(keys),
      );
    });

    test('wraps the English text in one left-to-right isolate', () {
      final english = AppLocalizationsEn();
      final isolated = IsolatedFallbackLocalizations();
      expect(isolated.localeName, 'en');
      expect(isolated.startOpenFile, '${_lri}Open file…$_pdi');
      expect(isolated.onboardingStep('1', '2'), '${_lri}1 of 2$_pdi');
      expect(
        isolated.onboardingFeatureLanguages(3, '3'),
        '${_lri}3 interface languages$_pdi',
      );
      expect(
        isolated.languageOptionNotTranslated('فارسی'),
        IsolatedFallbackLocalizations.isolate(
          english.languageOptionNotTranslated('فارسی'),
        ),
      );
      // A value already isolated (bidiIsolate) nests inside.
      expect(
        isolated.shellSavedOnDevice('\u206814:32$_pdi'),
        '${_lri}Saved on this device · \u206814:32$_pdi$_pdi',
      );
    });

    test("its delegate loads at once, for English, before the app's", () {
      const delegate = IsolatedFallbackLocalizations.delegate;
      expect(delegate.type, AppLocalizations);
      expect(delegate.isSupported(const Locale('en')), isTrue);
      expect(delegate.isSupported(const Locale('ar')), isFalse);
      expect(
        delegate.load(const Locale('en')),
        isA<SynchronousFuture<AppLocalizations>>(),
      );
      expect(delegate.shouldReload(delegate), isFalse);
      expect(IsolatedFallbackLocalizations.localizationsDelegates, [
        delegate,
        ...AppLocalizations.localizationsDelegates,
      ]);
    });

    test('is used for right-to-left languages without a translation', () {
      expect([
        for (final language in AppLanguage.values)
          if (language.isolatesFallbackStrings) language.tag,
      ], _isolated);
      for (final language in AppLanguage.values) {
        expect(
          language.isolatesFallbackStrings,
          language.rightToLeft && !language.translated,
          reason: language.tag,
        );
      }
    });
  });

  group('without isolates, English reorders in right to left', () {
    // The reason for the isolates, measured: a bare English string in a
    // right-to-left paragraph.
    for (final (text, parts) in const [
      ('1 of 2', ['1', 'of', '2']),
      ('Open file…', ['O', 'file', '…']),
      ('3 interface languages', ['3', 'interface', 'languages']),
    ]) {
      testWidgets('"$text" does not read in order bare, and does isolated', (
        tester,
      ) async {
        await tester.pumpWidget(
          Directionality(
            textDirection: TextDirection.rtl,
            child: Center(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Text(text),
                  SizedBox(
                    width: 600,
                    child: Text(IsolatedFallbackLocalizations.isolate(text)),
                  ),
                ],
              ),
            ),
          ),
        );
        expect(_readsInOrder(_paragraph(tester, text), text, parts), isFalse);
        final isolated = IsolatedFallbackLocalizations.isolate(text);
        final paragraph = _paragraph(tester, isolated);
        expect(_readsInOrder(paragraph, isolated, parts), isTrue);
        // The isolated string still sits at the start: the right.
        expect(paragraph.size.width, 600);
        expect(_rightmostGlyph(paragraph), closeTo(600, 0.5));
        expect(_left(paragraph, 1), greaterThan(300));
      });
    }
  });

  group('the app in Persian and Hebrew (G93)', () {
    for (final code in _isolated) {
      testWidgets('$code: "1 of 2", "Open file…" and "3 interface languages" '
          'read in order, at the start', (tester) async {
        final cases =
            <(M1Screen, String Function(AppLocalizations), List<String>)>[
              (
                M1Screen.privacyStep,
                (l10n) => l10n.onboardingStep('1', '2'),
                ['1', 'of', '2'],
              ),
              (
                M1Screen.start,
                (l10n) => l10n.startOpenFile,
                ['O', 'file', '…'],
              ),
              (
                M1Screen.freeStep,
                (l10n) => l10n.onboardingFeatureLanguages(3, '3'),
                ['3', 'interface', 'languages'],
              ),
            ];
        for (final (screen, message, parts) in cases) {
          await tester.pumpWidget(const SizedBox.shrink());
          final l10n = await _pump(tester, screen, code);
          expect(l10n, isA<IsolatedFallbackLocalizations>());
          final text = message(l10n);
          expect(text, startsWith(_lri), reason: text);
          expect(text, endsWith(_pdi), reason: text);
          expect(
            directionOf(tester, find.text(text)),
            TextDirection.rtl,
            reason: text,
          );
          final paragraph = _paragraph(tester, text);
          expect(_readsInOrder(paragraph, text, parts), isTrue, reason: text);
          expect(
            _rightmostGlyph(paragraph),
            closeTo(paragraph.size.width, 0.5),
            reason: '$text sits at the start (right)',
          );
        }
      });

      testWidgets('$code: every message on the start screen is isolated', (
        tester,
      ) async {
        await _pump(tester, M1Screen.start, code);
        // Every text but the shortcuts ("Ctrl+O", key caps), which are
        // data and need no isolate (letters on both sides of "+").
        final shortcut = RegExp(r'^(Ctrl|Alt|Shift|Esc|[A-Z0-9⌘⌥⇧⌃])(\+\S+)*$');
        final texts = _texts(
          tester,
        ).where((text) => text.trim().isNotEmpty && !shortcut.hasMatch(text));
        expect(texts.length, greaterThan(5));
        for (final text in texts) {
          expect(text, startsWith(_lri), reason: text);
          expect(text, endsWith(_pdi), reason: text);
        }
      });

      testWidgets("$code: a language's own name keeps its direction inside "
          'the isolate', (tester) async {
        final l10n = await _pump(tester, M1Screen.settingsLanguage, code);
        final language = AppLanguage.fromTag(code)!;
        final endonym = language.endonym;
        // The select shows the chosen language: "فارسی · Not translated
        // yet", in one isolate.
        final label = l10n.languageOptionNotTranslated(endonym);
        expect(
          label,
          IsolatedFallbackLocalizations.isolate(
            '$endonym · Not translated yet',
          ),
        );
        final paragraph = _paragraph(tester, label);
        // The endonym (offsets 1 to its length) reads right to left: its
        // first letter is to the right of its last.
        expect(
          _left(paragraph, 1),
          greaterThan(_left(paragraph, endonym.length)),
        );
        // The sentence keeps the English order: the name, then "Not
        // translated yet", from left to right.
        expect(
          _readsInOrder(paragraph, label, [
            endonym.characters.last,
            'Not',
            'translated',
            'yet',
          ]),
          isTrue,
        );
      });

      testWidgets('$code: screen readers read the same words as in English', (
        tester,
      ) async {
        final semantics = tester.ensureSemantics();
        var l10n = await _pump(tester, M1Screen.start, 'en');
        final english = tester.getSemantics(find.text(l10n.startOpenFile));
        final englishLabel = english.label;
        expect(englishLabel, contains('Open file…'));

        await tester.pumpWidget(const SizedBox.shrink());
        l10n = await _pump(tester, M1Screen.start, code);
        final node = tester.getSemantics(find.text(l10n.startOpenFile));
        expect(node.label, contains('Open file…'));
        expect(_withoutIsolates(node.label), englishLabel);
        expect(find.bySemanticsLabel(RegExp('Open file…')), findsWidgets);
        semantics.dispose();
      });
    }

    testWidgets('choosing Persian in Settings isolates the strings in place, '
        'and English removes the isolates', (tester) async {
      await _pump(tester, M1Screen.settingsLanguage, 'en');
      final state = tester.state(find.byType(FmSettings));
      Future<void> choose(AppLanguage language) async {
        tester
            .widget<Select<AppLanguage>>(find.byType(Select<AppLanguage>))
            .onChanged!(language);
        await tester.pumpAndSettle();
      }

      await choose(AppLanguage.persian);
      expect(
        find.text(IsolatedFallbackLocalizations.isolate('Settings')),
        findsOneWidget,
      );
      expect(find.text('Settings'), findsNothing);
      // The same screen, reloaded in place: nothing was rebuilt from scratch.
      expect(tester.state(find.byType(FmSettings)), same(state));

      await choose(AppLanguage.english);
      expect(find.text('Settings'), findsOneWidget);
      expect(_texts(tester).where((text) => text.contains(_lri)), isEmpty);
      expect(tester.state(find.byType(FmSettings)), same(state));
    });
  });

  group('other languages carry no fallback isolates', () {
    for (final code in _plain) {
      testWidgets('$code: no M1 screen has a left-to-right isolate', (
        tester,
      ) async {
        for (final screen in M1Screen.values) {
          await tester.pumpWidget(const SizedBox.shrink());
          final l10n = await _pump(tester, screen, code);
          expect(l10n, isNot(isA<IsolatedFallbackLocalizations>()));
          final marked = _texts(tester).where((text) => text.contains(_lri));
          expect(marked, isEmpty, reason: screen.description);
        }
      });
    }
  });
}
